insert into public.paginas_web(ruta,titulo,descripcion,encabezado,introduccion) values
('/','Alquiler de autos y camionetas en Lima','Alquiler de autos, camionetas y maquinaria en Lima para personas y empresas. Atención desde Santiago de Surco. Solicite su cotización.','Alquiler de autos, camionetas y maquinaria en Lima','Alquiler de autos y camionetas para personas y empresas, con atención personalizada desde Santiago de Surco, Lima.'),
('/flota/','Alquiler de camionetas y autos en Lima','Explore camionetas SUV, sedanes y autos familiares en Lima: Ford Territory, Changan X7 Plus, Toyota Yaris y más. Consulte disponibilidad.','Flota de autos y camionetas en alquiler en Lima','Camionetas SUV, sedanes y vehículos familiares para la movilidad de personas y empresas. Consulte fechas, modelos y condiciones.'),
('/nosotros/','Empresa de alquiler de autos en Surco','Renting Car A&M: alquiler de autos, camionetas y maquinaria con taller propio en Santiago de Surco, Lima. Atención a personas y empresas.','Renting Car A&M: alquiler de autos y maquinaria en Surco','Alquiler de autos, camionetas, maquinaria y transporte de carga para personas y empresas en Lima.'),
('/contacto/','Cotice su alquiler de auto en Surco','Cotice el alquiler de su auto, camioneta o maquinaria en Lima. Visítenos en Av. Santiago de Surco 3573, Surco, o escríbanos por WhatsApp.','Cotice el alquiler de su auto, camioneta o maquinaria','Comparta las fechas y características del servicio que necesita. Nuestro equipo en Santiago de Surco preparará su propuesta.'),
('/como-funciona/','Cómo alquilar un auto en Lima','Conozca los pasos para cotizar un auto o camioneta en Lima. Coordine documentos, garantía y entrega con Renting Car A&M en Surco.','Cómo alquilar un auto o camioneta en Lima','Elija su modelo y consulte los requisitos aplicables a su unidad antes de confirmar el alquiler.'),
('/maquinaria-y-transporte/','Alquiler de maquinaria pesada en Lima','Alquiler de maquinaria pesada en Lima: excavadora CAT 330DL, volquetes y transporte de carga con camiones Volvo y Scania. Cotice su proyecto.','Alquiler de maquinaria pesada y transporte de carga','Excavadora CAT 330DL, volquetes y transporte de carga en Lima. Consulte operador, movilización y condiciones para su proyecto.'),
('/maquinaria-y-transporte/excavadora-cat-330dl/','Alquiler de excavadora CAT 330DL en Lima','Alquiler de excavadora CAT 330DL en Lima para excavación y movimiento de tierras. Comparta ubicación y fechas; consulte operador y movilización.','Alquiler de excavadora CAT 330DL en Lima','Excavadora para zanjas, movimiento de tierras y carga de volquetes. Cuéntenos el trabajo y la ubicación de la obra para evaluar su solicitud.'),
('/maquinaria-y-transporte/volquetes/','Alquiler de volquetes en Lima','Alquiler de volquetes en Lima para eliminación de desmonte y traslado de material de obra. Comparta ubicación, fechas y volumen para cotizar.','Alquiler de volquetes en Lima','Volquetes para eliminación de desmonte, traslado de agregados y apoyo a obras. Indique volumen, tipo de material y recorrido.'),
('/maquinaria-y-transporte/transporte-de-carga/','Transporte de carga en Lima','Transporte de carga en Lima con camiones y tractos Volvo y Scania. Cotice su traslado indicando origen, destino, fechas y tipo de mercancía.','Transporte de carga pesada con camiones y tractos','Transporte de carga con camiones y tractos Volvo y Scania. Comparta la ruta, el peso y las dimensiones de su carga para evaluar el servicio.'),
('/alquiler-para-empresas/','Alquiler de camionetas para empresas','Alquiler de camionetas y autos para empresas en Lima. Atención directa desde Surco y taller propio. Consulte plazos y solicite una propuesta.','Alquiler de camionetas para empresas en Lima','Camionetas SUV y autos para la movilidad de su equipo de trabajo, con atención directa desde Santiago de Surco.')
on conflict(ruta) do nothing;
